<template><div class="workflow"><div class="actions"><el-button v-permission="'sales_automation:admin'" @click="openProfile">配置获客模型</el-button><el-button v-any-permission="['sales_automation:write','sales_automation:admin']" type="primary" @click="jobDialog=true">创建获客任务</el-button></div><el-alert v-if="workflowError" type="error" title="操作失败，请检查字段或权限后重试。" :closable="false" show-icon/><CustomerHubWorkspace :key="refreshKey" kind="acquisition"/><el-dialog v-model="jobDialog" title="创建获客任务" width="520"><el-form label-position="top"><el-form-item label="任务名称"><el-input v-model="job.name"/></el-form-item><el-form-item label="目标数量"><el-input-number v-model="job.target_count" :min="1" :max="500"/></el-form-item><el-form-item label="国家（逗号分隔）"><el-input v-model="job.countries"/></el-form-item></el-form><template #footer><el-button @click="jobDialog=false">取消</el-button><el-button v-any-permission="['sales_automation:write','sales_automation:admin']" type="primary" :loading="workflowLoading" @click="submitJob">创建</el-button></template></el-dialog><el-dialog v-model="profileDialog" title="配置获客模型" width="620"><el-form label-position="top"><el-form-item label="公司名称"><el-input v-model="form.company_name"/></el-form-item><el-form-item label="公司网站"><el-input v-model="form.company_website"/></el-form-item><el-form-item label="产品（逗号分隔）"><el-input v-model="form.productsText"/></el-form-item><el-form-item label="目标国家（逗号分隔）"><el-input v-model="form.countriesText"/></el-form-item><el-form-item label="策略版本"><el-input v-model="form.policy_version"/></el-form-item><el-form-item label="策略 JSON"><el-input v-model="form.policyText" type="textarea" :rows="6"/></el-form-item></el-form><template #footer><el-button @click="profileDialog=false">取消</el-button><el-button v-permission="'sales_automation:admin'" type="primary" :loading="workflowLoading" @click="submitProfile">保存</el-button></template></el-dialog></div></template>
<script setup>
import { reactive, ref } from 'vue';import { msgError, msgSuccess } from '@/utils/feedback';import CustomerHubWorkspace from './CustomerHubWorkspace.vue';import { useAcquisitionWorkflows } from './composables/useCustomerHub'
const {workflowLoading,workflowError,loadProfile,saveProfile,createJob}=useAcquisitionWorkflows();const refreshKey=ref(0),jobDialog=ref(false),profileDialog=ref(false);const job=reactive({name:'',target_count:20,countries:''});const form=reactive({company_name:'',company_website:'',productsText:'',countriesText:'',policy_version:'',policyText:'{}'});const split=v=>v.split(',').map(x=>x.trim()).filter(Boolean)
async function openProfile(){const p=await loadProfile();if(p)Object.assign(form,{...p,productsText:(p.products||[]).join(','),countriesText:(p.target_countries||[]).join(','),policyText:JSON.stringify(p.policy_json||{},null,2)});profileDialog.value=true}
async function submitJob(){if(await createJob({name:job.name,target_count:job.target_count,adapter:'agent',criteria_json:{countries:split(job.countries)}})){jobDialog.value=false;refreshKey.value++;msgSuccess('创建获客任务')}}
async function submitProfile(){let policy;try{policy=JSON.parse(form.policyText)}catch{msgError('策略 JSON 格式错误');return}if(await saveProfile({company_name:form.company_name,company_website:form.company_website||null,products:split(form.productsText),advantages:form.advantages||[],target_countries:split(form.countriesText),target_industries:form.target_industries||[],target_roles:form.target_roles||[],exclusions:form.exclusions||[],default_language:form.default_language||'en',policy_version:form.policy_version,policy_json:policy})){profileDialog.value=false;msgSuccess('保存获客模型')}}
</script><style scoped>.workflow{display:grid;gap:12px}.actions{display:flex;justify-content:flex-end;gap:8px}</style>
